from datetime import datetime, timedelta

def get_tomorrow_datetime():
    today = datetime.now()
    tomorrow = today + timedelta(days=1)
    return tomorrow.strftime("%Y-%m-%d %H:%M:%S")

def get_user_input():
    date_input = str(input("Enter date: "))
    time_input = str(input("Enter time: "))
    dt_str = f"{date_input} {time_input}:00"
    dt = datetime.strptime(dt_str, "%Y-%m-%d %H:%M:%S")

    return dt.isoweekday()

def get_time_until(dt):
    now = datetime.now()
    diff = dt - now
    return diff.total_seconds()

